// Write researched values into a 2026 winner profile.
//
// A result is { found, tried, retrieved, method } where found maps a profile field to { value, source }
// (hops, malts, yeast and adjuncts carry arrays). A value is written only into a field that is empty:
// nothing already in a profile is overwritten. Each written value is recorded in the `provenance`
// frontmatter list with its source URL, retrieval date and method. Every URL tried for a field that
// stays empty is added to that field's gaps entry. The derived sections are then regenerated by the
// deep dive generator.

import YAML from 'yaml';
import { deepDive, missingFields, orderKeys, serialize, splitDoc } from '../winner-deep-dive.mjs';
import { loadHopLookup, resolveHop } from './hop-aliases.mjs';
import { redact } from './redact.mjs';

const isBlank = (v) => v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
const hostLabel = (url) => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return String(url); } };
const mdLink = (url) => `[${hostLabel(url)}](${String(url).replace(/--/g, '-%2D')})`;

// Built from code points so this source carries no dash glyph itself.
const DASHES = String.fromCharCode(0x2013, 0x2014);
const DASH_BETWEEN_DIGITS = new RegExp(`(\\d)\\s*[${DASHES}-]\\s*(\\d)`, 'g');
const DASH_GLYPH = new RegExp(`\\s*[${DASHES}]\\s*`, 'g');

// Brewery wording keeps its words; a dash used as punctuation becomes a comma or "to".
export function cleanDashes(s) {
  return String(s)
    .replace(DASH_BETWEEN_DIGITS, '$1 to $2')
    .replace(DASH_GLYPH, ', ')
    .replace(/\s-{1,2}\s/g, ', ')
    .replace(/--+/g, ', ')
    .replace(/,\s*,/g, ',');
}

// Hop names from a list: each must resolve to a canonical variety, else none is written.
export function hopEntries(names, source, lookup) {
  const rows = [];
  for (const name of names) {
    const r = resolveHop(name, lookup);
    if (r.status !== 'mapped') return { rows: [], unresolved: name };
    rows.push({ published: name, variety: r.canonical, form: r.form ?? null, use: null, 'lot-or-farm': null, source });
  }
  return { rows, unresolved: null };
}

const SPEC_ROW = { abv: 'ABV', ibu: 'IBU', hops: 'Hops', malts: 'Malts and grains', yeast: 'Yeast', adjuncts: 'Adjuncts, fruit, spices' };

function setSpecRow(body, label, value, source) {
  const re = new RegExp(`^\\| ${label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')} \\|.*$`, 'm');
  const row = `| ${label} | ${String(value).replace(/\|/g, '&#124;')} | ${mdLink(source)} |`;
  return re.test(body) ? body.replace(re, row) : body;
}

function appendToSection(body, name, line) {
  const re = new RegExp(`(^## ${name}\\s*\\n[\\s\\S]*?)(?=^## |(?![\\s\\S]))`, 'm');
  if (!re.test(body)) return `${body.trimEnd()}\n\n## ${name}\n\n${line}\n`;
  return body.replace(re, (m, sect) => `${sect.trimEnd()}\n${line}\n\n`);
}

export function applyResult(text, ctx, result, { lookup = loadHopLookup(), file = '' } = {}) {
  const { data, blocks, body: body0 } = splitDoc(text);
  const d = { ...data };
  const changed = new Set();
  const put = (k, v) => { d[k] = v; changed.add(k); };
  const found = result.found ?? {};
  const prov = [...(Array.isArray(d.provenance) ? d.provenance : [])];
  const method = result.method ?? 'scraped from brewery site';
  const retrieved = result.retrieved;
  const wrote = [];
  const note = (field, value, source) => { prov.push({ field, value: String(value).slice(0, 160), source, retrieved, method }); wrote.push(field); };
  const sources = [...(d.sources ?? [])];
  const addSource = (u) => { if (u && !sources.includes(u)) sources.push(u); };
  let body = body0;

  const clean = (s) => cleanDashes(redact(s).text);
  const scalar = (field, key, shape) => {
    const f = found[field];
    if (!f || isBlank(f.value) || !isBlank(d[key])) return;
    if (shape === 'text') put(key, { text: clean(f.value), source: f.source });
    else if (shape === 'value') put(key, { value: clean(f.value), source: f.source });
    else put(key, f.value);
    note(key, f.value, f.source); addSource(f.source);
    if (SPEC_ROW[key]) body = setSpecRow(body, SPEC_ROW[key], key === 'abv' ? `${f.value}%` : f.value, f.source);
  };
  scalar('description', 'description', 'text');
  scalar('tasting-notes', 'tasting-notes', 'text');
  scalar('abv', 'abv'); scalar('ibu', 'ibu');
  scalar('srm', 'srm', 'value'); scalar('og', 'og', 'value'); scalar('fg', 'fg', 'value');
  scalar('water', 'water', 'value'); scalar('process', 'process', 'value');

  const list = (field) => {
    const f = found[field];
    if (!f || !f.value?.length || !isBlank(d[field])) return;
    const items = f.value.map((x) => clean(x));
    put(field, items); note(field, items.join(', '), f.source); addSource(f.source);
    body = setSpecRow(body, SPEC_ROW[field], items.join(', '), f.source);
  };
  list('malts'); list('yeast'); list('adjuncts');

  const hops = found.hops;
  if (hops && hops.value?.length && isBlank(d.hops)) {
    const { rows, unresolved } = hopEntries(hops.value, hops.source, lookup);
    if (unresolved) result.unresolved = [...(result.unresolved ?? []), `hop name not in the alias map: ${unresolved}`];
    else {
      put('hops', hops.value); put('hop-profile', rows); note('hops', hops.value.join(', '), hops.source); addSource(hops.source);
      body = setSpecRow(body, SPEC_ROW.hops, hops.value.join(', '), hops.source);
    }
  }

  if (changed.has('description')) {
    body = body.replace(/^## brewery-description\s*\n[\s\S]*?(?=^## |(?![\s\S]))/m, `## brewery-description\n\n> ${d.description.text}\n\nSource: ${mdLink(d.description.source)}\n\n`);
  }
  if (wrote.length) {
    const parts = [];
    for (const k of ['hops', 'malts', 'yeast', 'adjuncts']) if (changed.has(k)) parts.push(`${k}: ${d[k].join(', ')}`);
    if (parts.length) body = body.replace(/^## ingredients\s*\n[\s\S]*?(?=^## |(?![\s\S]))/m, `## ingredients\n\nPublished by the brewery: ${parts.join('; ')}. Sources are in the specs table.\n\n`);
  }

  if (changed.size) { put('provenance', prov); put('sources', sources); }
  // Gaps: every field still empty names the URLs tried.
  const tried = [...new Set(result.tried ?? [])];
  const prior = Array.isArray(d.gaps) ? d.gaps : [];
  const missing = missingFields(d);
  const gaps = missing.map((f) => {
    const hit = prior.find((g) => g.field === f);
    const checked = [...(hit?.['sources-checked'] ?? sources.filter((u) => !/brewers-association-beer-style-guidelines/.test(u)))];
    for (const u of tried) if (!checked.includes(u)) checked.push(u);
    return { field: f, 'sources-checked': checked };
  });
  if (JSON.stringify(gaps) !== JSON.stringify(prior)) put('gaps', gaps);

  if (tried.length || changed.size) {
    const got = wrote.length ? `wrote ${[...new Set(wrote)].join(', ')}` : 'found nothing new';
    body = appendToSection(body, 'research-notes', `- Brewery site scrape ${retrieved ?? ''}: ${got}; ${tried.length} page${tried.length === 1 ? '' : 's'} tried (robots.txt obeyed, one request every few seconds per host).`);
  }

  const keys = orderKeys([...new Set([...blocks.keys(), ...changed])]);
  const fm = keys.map((k) => (changed.has(k) ? serialize(k, d[k]) : blocks.get(k))).join('');
  const assembled = `---\n${fm}---\n\n${body.trimEnd()}\n`;
  YAML.parse(assembled.slice(4, assembled.indexOf('\n---', 4) + 1));
  return { text: deepDive(assembled, ctx, file), wrote: [...new Set(wrote)] };
}
